{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to correct for overconfidence.",
    "Reduce forecast magnitude by 5-10% if recent history shows mean reversion (true outcome < model forecast for 3+ consecutive days).",
    "Apply a lag correction: if true outcome is significantly lower than forecast, delay the peak by 1-2 days and reduce amplitude.",
    "Cap forecast spikes above 10% above recent 7-day high — sentiment-driven overreactions often overcorrect.",
    "If sentiment is positive (≥ 0.33) and forecast is below true outcome, increase forecast by 3-5% to capture sentiment-driven momentum.",
    "For long-term horizons (>14 days), apply a smoothing filter to reduce volatility — sentiment noise often distorts 30-day forecasts."
  ]
}
